def has_short_cycle(adj, u, v, max_len=6):
    # BFS from u avoiding edge u-v to find v within distance max_len-1
    # If path of length <= max_len-1 exists from u to v not using edge, adding edge creates cycle of length <= max_len
    from collections import deque
    dist = {u: 0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_len-1:
            continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x]+1
                if y == v:
                    return True
                q.append(y)
    return False

